/**
 * Bahasa Indonesia (id) UI strings.
 *
 * Timor-Leste's SME owner class was schooled in Indonesian (1975-1999), so this
 * is the working language of many of the people who actually sign up — read
 * more comfortably than written technical Tetun, and far more widely than
 * Portuguese.
 *
 * Two rules hold this file together:
 *   1. Institution and statute names are NEVER translated. INSS, WIT, ATTL,
 *      SEFOPE, TIN/NIF, NISS, "Lei 4/2012", "DL 20/2017", and the product names
 *      (Xefe, Ekipa, Kaixa, XefeBot) stay verbatim, exactly as in pt/tet — a
 *      reader has to be able to match them against the government's own forms.
 *   2. A string citing an article AND a number must keep the direction word
 *      ("minimal", "paling sedikit", "maksimal"), because Lei 4/2012 Art. 1(2)
 *      makes the Labour Code a floor. scripts/check-statutory-copy.ts enforces
 *      this and knows the Indonesian words.
 */
