        a1: "Ya. Xefe menghitung pemotongan WIT, iuran INSS, lembur dan subsídio anual bulan ke-13 pada setiap proses penggajian, dan menjaga setiap jumlah tetap terlihat untuk diperiksa sebelum Anda menyelesaikannya.",
